style.css:
@-moz-document domain("head-fi.org") {
/* Main Layout Backgrounds */
    body, html, #mainbody-actual, .p-pageWrapper, .p-body, .p-sectionMain {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Content Cards & Forum Blocks */
    .block-container, .blockMessage, .p-body-sidebar .block, .structItem {
        background-color: #1e1e1e !important;
        border-color: #2d2d2d !important;
        color: #e0e0e0 !important;
    }

    /* Navigation & Header Bars */
    .p-nav, .p-nav-inner, .p-header, .p-sectionMain-header {
        background-color: #1a1a1a !important;
        border-bottom: 1px solid #2d2d2d !important;
    }
    
    .p-navEl, .p-navEl a, .p-navEl-link {
        color: #b3b3b3 !important;
    }

    /* Forum Threads & Post Boxes */
    .message-inner, .message-cell, .message-main {
        background-color: #1c1c1c !important;
        color: #e0e0e0 !important;
        border-color: #2d2d2d !important;
    }
    
    .message-cell.message-cell--user {
        background-color: #161616 !important;
        border-right: 1px solid #2d2d2d !important;
    }

    /* Thread Lists Hover Effects */
    .structItem:hover, .structItem--container:hover {
        background-color: #252525 !important;
    }

    /* Typography, Links & Headings */
    h1, h2, h3, h4, .p-title-value {
        color: #ffffff !important;
    }

    a, .link {
        color: #3b9eff !important;
    }

    a:hover {
        color: #6bb5ff !important;
        text-decoration: underline !important;
    }
    
    /* Muted Text & Timestamps */
    .u-muted, .pairs > dt, .structItem-meta {
        color: #888888 !important;
    }

    /* Inputs, Buttons, & Search Bars */
    input, select, textarea, .input, .button, .js-titleInput {
        background-color: #2a2a2a !important;
        color: #ffffff !important;
        border: 1px solid #444444 !important;
    }
    
    .button.button--cta {
        background-color: #ff9900 !important;
        color: #121212 !important;
    }

    /* Code Blocks & Quotes */
    .bbCodeBlock, .bbCodeBlock-title, .bbCodeBlock-expandLink {
        background-color: #262626 !important;
        border-left: 3px solid #ff9900 !important;
        color: #dcdcdc !important;
    }
    
    .bbCodeBlock-content {
        background-color: #1e1e1e !important;
    }

    /* Pagination / Page Nav */
    .pageNav-page, .pageNav-jump {
        background-color: #2a2a2a !important;
        color: #e0e0e0 !important;
        border-color: #3a3a3a !important;
    }

    .pageNav-page.pageNav-page--current {
        background-color: #ff9900 !important;
        color: #121212 !important;
        border-color: #ff9900 !important;
    }
}
